css:
.kgs { font-size: 10pt; line-height: 1.5; }
.kgs-kopf { overflow: hidden; }
.kgs-kopf strong { float: left; font-size: 12pt; }
.kgs-kopf span { float: right; }
.kgs-adresse { margin-top: 30mm; }
.kgs h1 { font-size: 14pt; margin-top: 12mm; }
.kgs-daten { width: 100%; margin: 4mm 0; }
.kgs-daten td { padding: 1mm 2mm; vertical-align: top; }
.kgs-daten td:first-child { width: 55mm; color: #666; }
.kgs-block { margin-top: 4mm; }
.kgs-unterschrift { width: 100%; margin-top: 20mm; }
.kgs-unterschrift td { border-top: 1px solid #000; padding-top: 1mm; width: 45%; }
.kgs-unterschrift td:nth-child(2) { border-top: 0; width: 10%; }
.kgs-text { white-space: pre-wrap; margin: 1mm 0 0 0; }
